-- ACADLYX LMS production completion (additive only)
ALTER TABLE "notices" ADD COLUMN IF NOT EXISTS "courseOfferingId" TEXT;
CREATE INDEX IF NOT EXISTS "notices_institutionId_courseOfferingId_publishedAt_idx" ON "notices"("institutionId","courseOfferingId","publishedAt");
CREATE TABLE IF NOT EXISTS "lms_course_workflows" ("id" TEXT PRIMARY KEY,"institutionId" TEXT NOT NULL,"courseOfferingId" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL DEFAULT 'DRAFT',"submittedById" TEXT,"submittedAt" TIMESTAMP(3),"approvedById" TEXT,"approvedAt" TIMESTAMP(3),"rejectedById" TEXT,"rejectedAt" TIMESTAMP(3),"rejectionReason" TEXT,"publishedAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "lms_course_workflows_institution_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE,CONSTRAINT "lms_course_workflows_offering_fkey" FOREIGN KEY ("courseOfferingId") REFERENCES "course_offerings"("id") ON DELETE CASCADE,CONSTRAINT "lms_course_workflows_status_check" CHECK ("status" IN ('DRAFT','PENDING_APPROVAL','APPROVED','PUBLISHED','REJECTED','ARCHIVED')));
CREATE INDEX IF NOT EXISTS "lms_course_workflows_institution_status_idx" ON "lms_course_workflows"("institutionId","status");
CREATE TABLE IF NOT EXISTS "lms_lesson_files" ("id" TEXT PRIMARY KEY,"institutionId" TEXT NOT NULL,"lessonResourceId" TEXT NOT NULL,"fileAssetId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "lms_lesson_files_institution_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE,CONSTRAINT "lms_lesson_files_resource_fkey" FOREIGN KEY ("lessonResourceId") REFERENCES "lesson_resources"("id") ON DELETE CASCADE,CONSTRAINT "lms_lesson_files_asset_fkey" FOREIGN KEY ("fileAssetId") REFERENCES "file_assets"("id") ON DELETE CASCADE,CONSTRAINT "lms_lesson_files_unique" UNIQUE ("lessonResourceId","fileAssetId"));
CREATE TABLE IF NOT EXISTS "lms_submission_files" ("id" TEXT PRIMARY KEY,"institutionId" TEXT NOT NULL,"submissionId" TEXT NOT NULL,"fileAssetId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "lms_submission_files_institution_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE,CONSTRAINT "lms_submission_files_submission_fkey" FOREIGN KEY ("submissionId") REFERENCES "assignment_submissions"("id") ON DELETE CASCADE,CONSTRAINT "lms_submission_files_asset_fkey" FOREIGN KEY ("fileAssetId") REFERENCES "file_assets"("id") ON DELETE CASCADE,CONSTRAINT "lms_submission_files_unique" UNIQUE ("submissionId","fileAssetId"));
CREATE TABLE IF NOT EXISTS "lms_discussions" ("id" TEXT PRIMARY KEY,"institutionId" TEXT NOT NULL,"courseOfferingId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"parentId" TEXT,"body" TEXT NOT NULL,"isPinned" BOOLEAN NOT NULL DEFAULT FALSE,"isLocked" BOOLEAN NOT NULL DEFAULT FALSE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "lms_discussions_institution_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE,CONSTRAINT "lms_discussions_offering_fkey" FOREIGN KEY ("courseOfferingId") REFERENCES "course_offerings"("id") ON DELETE CASCADE,CONSTRAINT "lms_discussions_author_fkey" FOREIGN KEY ("authorId") REFERENCES "users"("id") ON DELETE CASCADE,CONSTRAINT "lms_discussions_parent_fkey" FOREIGN KEY ("parentId") REFERENCES "lms_discussions"("id") ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "lms_discussions_offering_created_idx" ON "lms_discussions"("courseOfferingId","createdAt");
CREATE TABLE IF NOT EXISTS "lms_live_classes" ("id" TEXT PRIMARY KEY,"institutionId" TEXT NOT NULL,"courseOfferingId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"meetingUrl" TEXT,"provider" TEXT,"status" TEXT NOT NULL DEFAULT 'SCHEDULED',"recordingFileAssetId" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "lms_live_classes_institution_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE,CONSTRAINT "lms_live_classes_offering_fkey" FOREIGN KEY ("courseOfferingId") REFERENCES "course_offerings"("id") ON DELETE CASCADE,CONSTRAINT "lms_live_classes_asset_fkey" FOREIGN KEY ("recordingFileAssetId") REFERENCES "file_assets"("id") ON DELETE SET NULL,CONSTRAINT "lms_live_classes_creator_fkey" FOREIGN KEY ("createdById") REFERENCES "users"("id") ON DELETE RESTRICT,CONSTRAINT "lms_live_classes_window_check" CHECK ("endsAt" > "startsAt"),CONSTRAINT "lms_live_classes_status_check" CHECK ("status" IN ('SCHEDULED','LIVE','ENDED','CANCELLED')));
CREATE INDEX IF NOT EXISTS "lms_live_classes_offering_start_idx" ON "lms_live_classes"("courseOfferingId","startsAt");
CREATE TABLE IF NOT EXISTS "lms_settings" ("institutionId" TEXT PRIMARY KEY,"approvalRequired" BOOLEAN NOT NULL DEFAULT TRUE,"allowStudentDiscussions" BOOLEAN NOT NULL DEFAULT TRUE,"allowParentVisibility" BOOLEAN NOT NULL DEFAULT TRUE,"completionThreshold" INTEGER NOT NULL DEFAULT 80,"certificateEnabled" BOOLEAN NOT NULL DEFAULT TRUE,"allowExternalLinks" BOOLEAN NOT NULL DEFAULT FALSE,"maxResourceSizeMb" INTEGER NOT NULL DEFAULT 25,"defaultLiveProvider" TEXT,"updatedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "lms_settings_institution_fkey" FOREIGN KEY ("institutionId") REFERENCES "institutions"("id") ON DELETE CASCADE,CONSTRAINT "lms_settings_updated_by_fkey" FOREIGN KEY ("updatedById") REFERENCES "users"("id") ON DELETE SET NULL,CONSTRAINT "lms_settings_completion_check" CHECK ("completionThreshold" BETWEEN 1 AND 100),CONSTRAINT "lms_settings_size_check" CHECK ("maxResourceSizeMb" BETWEEN 1 AND 500));